    if a == b:
        return 0
    elif (a, b) in [(1, 2), (2, 3), (3, 1)]:
        return 1
    else:
        return -1

def compute_score(l1, l2):
    total = 0
    c1 = c2 = 0
    while l1 or l2:
        try:
            if c1 == 0:
                c1 = l1.pop()
            if c2 == 0:
                c2 = l2.pop()
        except IndexError:
            return total
        total += max(0, min(c1[0], c2[0]) * get_match(c1[1], c2[1]))
        if c1[0] < c2[0]:
            c2 = [c2[0] - c1[0], c2[1]]
