        elif c1[0] > c2[0]:
            c1 = [c1[0] - c2[0], c1[1]]
            c2 = 0
        else:
            c1 = c2 = 0
    return total

def find_min_score():
    perms1 = [list(p) for p in permutations([[rock1, 1], [sci1, 2], [paper1, 3]])]
    perms2 = [list(p) for p in permutations([[rock2, 1], [sci2, 2], [paper2, 3]])]
    min_ans = float('inf')
    for p1 in perms1:
        for p2 in perms2:
            p1_copy = [temp[:] for temp in p1]
            p2_copy = [temp[:] for temp in p2]
            min_ans = min(min_ans, compute_score(p1_copy, p2_copy))
